bad = []
for dp, dn, fn in os.walk(os.path.join(ROOT, 'scratch', 'proposal')):
    for n in fn:
        p = os.path.join(dp, n)
        for i, line in enumerate(open(p, encoding='utf-8', errors='replace')):
            if banned.search(line) and not any(a.lower() in line.lower() for a in allow):
                bad.append('%s:%d' % (os.path.relpath(p, ROOT), i + 1))

